        tree = bpy.data.node_groups.new(name, 'GeometryNodeTree')
        for socket_name, kind in [('Curves', 'NodeSocketGeometry'), ('Path', 'NodeSocketInt'),
                                 ('Start', 'NodeSocketFloat'), ('End', 'NodeSocketFloat'),
                                 ('Reach', 'NodeSocketFloat'), ('Axis', 'NodeSocketVector')]:
            tree.interface.new_socket(name=socket_name, in_out='INPUT', socket_type=kind)
        tree.interface.new_socket(name='Error', in_out='OUTPUT', socket_type='NodeSocketFloat')
        h = _Nodes(tree)
