def _unique_metric_rows(g, geometry):
    """Remove exact duplicate float stations after the spatial merge.

    Spatial hashing at a tiny merge distance can retain coincident vertices.
    In this ordered scalar domain an exact comparison proves duplication;
    distinct physical stations, however close, are left unchanged.
    """
    index=g.node('GeometryNodeInputIndex','Ordered station identity').outputs[0]
    metric=g.named('st_bundle_metric','FLOAT')
    previous=g.sample(geometry,metric,g.math('MAXIMUM',0.,g.math('SUBTRACT',index,1.)),'FLOAT')
    keep=g.either(g.compare(index,0,kind='INT'),g.compare(metric,previous,'GREATER_THAN'))
    return _select(g,geometry,keep,'Keep one row per exact physical station')


def _union_metric(g, geometries):
    index = g.node('GeometryNodeInputIndex', 'Unique physical station index').outputs[0]
    joined = _join(g, *geometries)
    positioned = g.node('GeometryNodeSetPosition', 'Physical axial station coordinates')
    g.set(joined, positioned.inputs['Geometry'])
    g.set(g.xyz(g.named('st_bundle_metric', 'FLOAT')), positioned.inputs['Position'])
    merge = g.node('GeometryNodeMergeByDistance', 'Merge only coincident physical stations')
    merge.inputs['Distance'].default_value = 1e-5
    g.set(positioned.outputs['Geometry'], merge.inputs['Geometry'])
    return _sorted(g, merge.outputs['Geometry'], g.named('st_bundle_metric', 'FLOAT'),
                   'Order all boundary controls and gap events')


def replace_saved_station_uniqueness(roots):
    """Experimental exact deduplication, applied only by the private exporter.

    Candidate 33 did not fix the translated curved Bundle regression. Keep
    this separate from the normal constructor until independent evidence
    establishes a benefit; near-coincident physical rows remain unresolved.
    """
    from .path_surface_nodes import _Nodes
    seen=set();pending=list(roots);targets=[]
    while pending:
        tree=pending.pop()
        if tree.as_pointer() in seen:continue
        seen.add(tree.as_pointer())
        if any(n.label=='Order all boundary controls and gap events' for n in tree.nodes):targets.append(tree)
        pending.extend(n.node_tree for n in tree.nodes if n.type=='GROUP' and n.node_tree)
    changed=[]
    for original in targets:
        if original.get('st_bundle_unique_stations'):continue
        tree=original.copy();tree.name=original.name+' / Unique station rows'
        g=_Nodes(tree)
        for node in list(tree.nodes):
            if node.label!='Order all boundary controls and gap events':continue
            output=node.outputs['Geometry'];consumers=[link.to_socket for link in output.links]
            checked=_unique_metric_rows(g,output)
            for socket in consumers:
                for link in list(socket.links):
                    if link.from_socket==output:tree.links.remove(link)
                g.set(checked,socket)
        tree['st_bundle_unique_stations']=1
        original.user_remap(tree);changed.append(tree.name)
    if not changed:raise ValueError('No saved Bundle station unions to upgrade')
    return changed


def _smooth_macro_anchors(g, length, target_cell):
    """Bounded coarse intervals for local smooth-curve error refinement.

    Smooth controls are certification samples, not required surface rows.
    Refinement still checks every original physical boundary knot. A regular
    coarse partition avoids nearly coincident anchors from different offsets.
    """
    from .bundle_resample_nodes import MAX_ROWS
    count=g.math('MAXIMUM',1.,g.math('CEIL',g.math('DIVIDE',length,
        g.math('MAXIMUM',.01,g.math('MULTIPLY',8.,target_cell)))))
    count=g.math('MINIMUM',MAX_ROWS-1,count)
    line=g.node('GeometryNodeMeshLine','Coarse intervals for local smooth Bundle refinement')
    g.set(g.math('ADD',count,1.),line.inputs['Count'])
    index=g.node('GeometryNodeInputIndex','Smooth macro interval endpoint').outputs[0]
    metric=g.math('MULTIPLY',length,g.math('DIVIDE',index,count))
    return g.store(line.outputs['Mesh'],'st_bundle_metric',metric)


def construct(g, curves, owner, partner, target_cell, minimum_band, edge_data, *, transition_cell_size=None,
              axis_override=None, clip_terminal_samples=None, align_free_terminals=None, regular_sampling=False,
              event_sampling=False, cap_free_ends=None, local_terminal_chart=False,narrow_terminal_caps=False,
              finite_terminal_contact=False, uniform_separated=False, uniform_mixed=False,
              independent_terminal_charts=False, independent_free_caps=False):
    """Return table, ny, validity/code, physical query callback and axis length.

    ``edge_data(rank_t)`` supplies raw oa,ia,ib,ob and optional ignored fields.
    ``query(metric_s)`` returns those four physical common-fibre hits, signed
    gap and mapping validity. Both use the caller's actual physical offsets.
    """
    index = g.node('GeometryNodeInputIndex', 'Physical Bundle station or interval').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Temporary axial lookup position').outputs[0]
    ends0, ends1 = edge_data(0.), edge_data(1.)
    origin = _mix(g, ends0[0], ends0[3])
    end = _mix(g, ends1[0], ends1[3])
    vector = g.vector('SUBTRACT', end, origin)
    length = g.vector('LENGTH', vector)
    axis = g.vector('NORMALIZE', vector)
    if axis_override is not None:
        active, specified = axis_override
        axis = g.switch(active, axis, specified, 'VECTOR')
        length = g.switch(active, length, g.vector('DOT_PRODUCT', vector, axis))
    source, nsource, boundary_valid = _boundary_stations(g, curves, owner, partner, axis,
        error_limit=.001 if regular_sampling else BOUNDARY_ERROR, preserve_controls=uniform_separated)
    # Optional free-end chart: give each physical boundary its own positive
    # axial interval. This only changes lookup coordinates, never curb points.
    # The caller restricts this whole-length chart to fully separated free
    # Bundles. The optional local chart below instead proves separated ends
    # and retains true common fibres for all interior overlap/contact events.
    terminal_metrics=[tuple(g.vector('DOT_PRODUCT',g.vector('SUBTRACT',ends[k],origin),axis)
                            for ends in (ends0,ends1)) for k in range(4)]
    terminal_alignment=False
    matching_ends = None
    if align_free_terminals is not None:
        matching=g.all(*(g.all(g.close(a,0.,AXIS_TOLERANCE),g.close(b,length,AXIS_TOLERANCE))
                         for a,b in terminal_metrics))
        terminal_alignment=g.all(align_free_terminals,g.boolean('NOT',matching))
        if independent_free_caps:
            matching_ends = [g.all(*(g.close(pair[side], length if side else 0., AXIS_TOLERANCE)
                                    for pair in terminal_metrics)) for side in (0, 1)]
    transverse = g.right(axis)
    # Sign of the physical transverse direction from the owner to partner.
    side = g.switch(g.compare(g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ends0[3], ends0[0]), transverse),
                              0., 'GREATER_THAN'), -1., 1.)
    lateral = g.vector('SCALE', transverse, side)
    values = edge_data(g.named('st_station_t', 'FLOAT'))[:4]
    raw_boundaries = None
    cap_body = None
    cap_active = False
    independent_cap_active = False
    cap_ends = None
    cap_depth = None
    if cap_free_ends is not None:
        from . import bundle_free_body_nodes
        raw_boundaries = [g.store(source, 'st_axis_xy', value, 'FLOAT_VECTOR') for value in values]
        cap_body = g.node('GeometryNodeGroup', 'True common-fibre body behind unchanged free-end caps')
        cap_body.node_tree = bundle_free_body_nodes.build(independent_ends=independent_free_caps)
        for k, boundary in enumerate(raw_boundaries):
            g.set(boundary, cap_body.inputs['Boundary '+str(k)])
        g.set(axis, cap_body.inputs['Axis'])
        # This branch treats complete free-end overlap caps. Other existing
        # branches remain responsible for separated or attached ends. Final
        # cap construction must independently qualify the original union.
        ends_overlap = [];ends_cap_eligible=[]
        for ends in (ends0, ends1):
            gap = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ends[2], ends[1]), lateral)
            own_left = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ends[2], ends[0]), lateral)
            own_right = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ends[3], ends[1]), lateral)
            overlap=g.all(g.compare(gap, -1e-5, 'LESS_THAN'),
                g.compare(own_left, 0., 'GREATER_THAN'), g.compare(own_right, 0., 'GREATER_THAN'))
            ends_overlap.append(overlap)
            if narrow_terminal_caps:
                narrow=g.all(g.compare(gap,0. if finite_terminal_contact else 4e-6,
                                       'GREATER_EQUAL' if finite_terminal_contact else 'GREATER_THAN'),
                             g.compare(gap,g.math('SUBTRACT',minimum_band,1e-5),'LESS_THAN'))
                ends_cap_eligible.append(g.either(overlap,narrow))
        cap_active = g.all(cap_free_ends, *ends_overlap)
        if narrow_terminal_caps:
            # This dispatch is only a proposal. Both complete finite end
            # perimeters, profiles and exact seams are checked by the cap
            # constructor before any mesh is accepted. Matching baselines
            # retain their original body construction.
            cap_active=g.either(cap_active,g.all(cap_free_ends,terminal_alignment,*ends_cap_eligible))
        if independent_free_caps:
            if matching_ends is None or not narrow_terminal_caps:
                raise ValueError('Independent free caps require terminal alignment and finite cap eligibility')
            requested = [g.all(eligible, g.boolean('NOT', matching))
                         for eligible, matching in zip(ends_cap_eligible, matching_ends)]
            # The new branch needs an actual cap at one end and an unchanged
            # physical plane at the other. It cannot use a coordinate warp to
            # fake the union of overlapping finite carriageway ends.
            independent_cap_active = g.all(cap_free_ends, g.boolean('NOT', cap_active),
                g.either(*requested), *(g.either(cap, matching) for cap, matching in zip(requested, matching_ends)))
            cap_ends = [g.switch(independent_cap_active, True, cap, 'BOOLEAN') for cap in requested]
            for side, active in zip(('Start', 'End'), cap_ends):
                g.set(active, cap_body.inputs['Cut '+side])
            cap_active = g.either(cap_active, independent_cap_active)
            from . import bundle_terminal_run_nodes
            cap_depth = bundle_terminal_run_nodes.cap_depth(g, target_cell, independent_cap_active)
            g.set(cap_depth, cap_body.inputs['Maximum Depth'])
            enabled = [g.all(independent_cap_active, active) for active in cap_ends]
            raw_boundaries = [bundle_terminal_run_nodes.evaluate(g, boundary, axis, enabled)
                              for boundary in raw_boundaries]
            for k, boundary in enumerate(raw_boundaries):
                g.set(boundary, cap_body.inputs['Boundary '+str(k)])
        origin = g.switch(cap_active, origin, cap_body.outputs['Origin'], 'VECTOR')
        length = g.switch(cap_active, length, cap_body.outputs['Length'])
        terminal_alignment = g.all(terminal_alignment, g.boolean('NOT', cap_active))
    local_chart = False
    local_records = None
    identity_ends = None
    if local_terminal_chart:
        if cap_body is None:
            raise ValueError('Local terminal chart requires physical cut boundaries')
        from . import bundle_terminal_chart_nodes
        if independent_terminal_charts:
            identity_ends = bundle_terminal_chart_nodes.end_identity(g, raw_boundaries, origin, axis, length)
        local_records, separated_ends = bundle_terminal_chart_nodes.construct(g, raw_boundaries,
            [cap_body.outputs['Boundary '+str(k)] for k in range(4)],
            origin, axis, lateral, length, minimum_band, cap_body.outputs['Valid'], identity_ends=identity_ends)
        local_chart = g.all(terminal_alignment, separated_ends)
    global_alignment = g.all(terminal_alignment, g.boolean('NOT', local_chart)) if local_terminal_chart else terminal_alignment
    lookups, metric_parts, checks = [], [], [g.compare(length, 1e-4, 'GREATER_THAN')]
    if cap_body is not None:
        checks.append(g.either(g.boolean('NOT', cap_active), cap_body.outputs['Valid']))
    for k, value in enumerate(values):
        metric = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', value, origin), axis)
        if align_free_terminals is not None:
            start_metric,end_metric=terminal_metrics[k]
            span=g.math('SUBTRACT',end_metric,start_metric)
            checks.append(g.either(g.boolean('NOT',terminal_alignment),
                g.compare(span,1e-4,'GREATER_THAN')))
            aligned=g.math('MULTIPLY',length,g.math('DIVIDE',g.math('SUBTRACT',metric,start_metric),span))
            aligned=g.switch(g.compare(index,0,kind='INT'),aligned,0.)
            aligned=g.switch(g.compare(index,g.math('SUBTRACT',nsource,1.),kind='INT'),aligned,length)
            metric=g.switch(global_alignment,metric,aligned)
        if clip_terminal_samples is not None:
            metric, cut_valid = _cut_metric(g, metric, index, nsource, length, value,
                                           origin, clip_terminal_samples)
            checks.append(g.stat(source, cut_valid))
        recorded = g.store(source, 'st_axis_xy', value, 'FLOAT_VECTOR')
        recorded = g.store(recorded, 'st_bundle_metric', metric)
        if clip_terminal_samples is not None:
            # The oblique endpoint is on the same straight physical offset
            # line as its certified lead. Some early/late normal samples are
            # outside that cut. Keep every sample in its original order within
            # the interval and retain the exact terminal cut vertices.
            endpoint = g.either(g.compare(index, 0, kind='INT'),
                                g.compare(index, g.math('SUBTRACT', nsource, 1.), kind='INT'))
            interior = g.all(g.compare(metric, AXIS_TOLERANCE, 'GREATER_THAN'),
                g.compare(metric, g.math('SUBTRACT', length, AXIS_TOLERANCE), 'LESS_THAN'))
            trimmed = _select(g, recorded, g.either(endpoint, interior), 'Clip certified boundary to its mouth planes')
            recorded = g.switch(clip_terminal_samples, recorded, trimmed, 'GEOMETRY')
        if cap_body is not None:
            recorded = g.switch(cap_active, recorded, cap_body.outputs['Boundary '+str(k)], 'GEOMETRY')
        if local_records is not None:
            recorded = g.switch(local_chart, recorded, local_records[k], 'GEOMETRY')
        nrecorded = _size(g, recorded)
        metric = g.named('st_bundle_metric', 'FLOAT')
        previous = g.sample(recorded, g.named('st_bundle_metric', 'FLOAT'), g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)), 'FLOAT')
        checks.append(g.stat(recorded, g.either(g.compare(index, 0, kind='INT'),
                          g.compare(g.math('SUBTRACT', metric, previous), AXIS_TOLERANCE, 'GREATER_THAN'))))
        first = g.sample(recorded, g.named('st_bundle_metric', 'FLOAT'), 0, 'FLOAT')
        last = g.sample(recorded, g.named('st_bundle_metric', 'FLOAT'), g.math('SUBTRACT', nrecorded, 1.), 'FLOAT')
        checks.extend((g.close(first, 0., AXIS_TOLERANCE), g.close(last, length, AXIS_TOLERANCE)))
        positioned = g.node('GeometryNodeSetPosition', 'Monotone boundary '+str(k)+' physical-axis lookup')
        g.set(recorded, positioned.inputs['Geometry']); g.set(g.xyz(metric), positioned.inputs['Position'])
        curve = g.node('GeometryNodeMeshToCurve', 'Boundary lookup preserves every physical corner')
        g.set(positioned.outputs['Geometry'], curve.inputs['Mesh'])
        lookup = curve.outputs['Curve']
        if clip_terminal_samples is not None:
            # A cut can leave the exact first/last vertex isolated after deleting
            # out-of-domain samples. Rebuild ordered connectivity only after the
            # independent monotonicity check above; never hide a folded edge.
            points = g.node('GeometryNodeMeshToPoints', 'Every retained boundary point, including isolated cuts')
            points.mode = 'VERTICES'; g.set(positioned.outputs['Geometry'], points.inputs['Mesh'])
            ordered = g.node('GeometryNodePointsToCurves', 'Connect clipped physical boundary samples in their original order')
            g.set(points.outputs['Points'], ordered.inputs['Points']); g.set(index, ordered.inputs['Weight'])
            lookup = g.switch(clip_terminal_samples, lookup, ordered.outputs['Curves'], 'GEOMETRY')
        lookups.append(lookup); metric_parts.append(recorded)
    mapping_valid = g.all(*checks)

    def query(s):
        points = []
        if event_sampling:
            from . import bundle_lookup_nodes
            points=bundle_lookup_nodes.evaluate(g,lookups,s)
        else:
            for curve in lookups:
                sample = g.node('GeometryNodeSampleCurve', 'Actual boundary hit on one common physical fibre')
                sample.mode = 'LENGTH'; sample.data_type = 'FLOAT_VECTOR'
                g.set(curve, sample.inputs['Curves']); g.set(s, sample.inputs['Length'])
                g.set(g.named('st_axis_xy', 'FLOAT_VECTOR'), sample.inputs['Value'])
                points.append(sample.outputs['Value'])
        gap = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', points[2], points[1]), lateral)
        return (*points, gap, mapping_valid)

    def source_rank(s, boundary):
        sample = g.node('GeometryNodeSampleCurve', 'Source member span at a physical boundary station')
        sample.mode = 'LENGTH'; sample.data_type = 'FLOAT'
        g.set(lookups[boundary], sample.inputs['Curves']); g.set(s, sample.inputs['Length'])
        g.set(g.named('st_station_t', 'FLOAT'), sample.inputs['Value'])
        return sample.outputs['Value']

    mandatory = _union_metric(g, metric_parts)
    if event_sampling:
        # Event discovery must retain every distinct scalar breakpoint. The
        # positional merge used by the legacy mesh rows is not sufficient for
        # proving that an interval has no topology changes.
        mandatory=_unique_metric_rows(g,_sorted(g,_join(g,*metric_parts),
            g.named('st_bundle_metric','FLOAT'),'Exact source knots for all Bundle topology events'))
    count = _size(g, mandatory)
    mandatory = g.store(mandatory, 'st_bundle_gap', query(g.named('st_bundle_metric', 'FLOAT'))[4])
    # All physical boundaries are affine between this union of their controls.
    # Every topology/ownership event can therefore be inserted exactly.
    events = []
    for event_kind in range(6):
        line = g.node('GeometryNodeMeshLine', 'Exact linear Bundle event '+str(event_kind))
        g.set(g.math('SUBTRACT', count, 1.), line.inputs['Count'])
        sa = g.sample(mandatory, g.named('st_bundle_metric', 'FLOAT'), index, 'FLOAT')
        sb = g.sample(mandatory, g.named('st_bundle_metric', 'FLOAT'), g.math('ADD', index, 1.), 'FLOAT')
        a, b = query(sa), query(sb)
        if event_kind < 2 or event_kind >= 4:
            threshold = (0. if event_kind == 0 else minimum_band if event_kind == 1 else
                         g.math('MULTIPLY', -2. if event_kind == 4 else 2., minimum_band))
            fa, fb = g.math('SUBTRACT', a[4], threshold), g.math('SUBTRACT', b[4], threshold)
        else:
            x, y = ((2, 0) if event_kind == 2 else (1, 3))
            fa = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', a[x], a[y]), lateral)
            fb = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', b[x], b[y]), lateral)
        crosses = g.compare(g.math('MULTIPLY', fa, fb), 0., 'LESS_THAN')
        fraction = g.math('DIVIDE', fa, g.math('SUBTRACT', fa, fb))
        metric = g.math('ADD', sa, g.math('MULTIPLY', fraction, g.math('SUBTRACT', sb, sa)))
        part = g.store(line.outputs['Mesh'], 'st_bundle_metric', metric)
        part = g.store(part, 'st_bundle_gap_event', event_kind+1, 'INT')
        events.append(_select(g, part, crosses, 'All strict linear gap or containment transitions'))
        if event_sampling:
            at=query(g.named('st_bundle_metric','FLOAT'))
            if event_kind < 2 or event_kind >= 4:
                value=g.math('SUBTRACT',at[4],threshold)
            else:
                value=g.vector('DOT_PRODUCT',g.vector('SUBTRACT',at[x],at[y]),lateral)
            previous=g.sample(mandatory,value,g.math('MAXIMUM',0.,g.math('SUBTRACT',index,1.)),'FLOAT')
            following=g.sample(mandatory,value,g.math('MINIMUM',g.math('SUBTRACT',count,1.),g.math('ADD',index,1.)),'FLOAT')
            # FLOAT Equal has a default epsilon; exact event identity must not
            # turn a near-threshold knot into a second, displaced event.
            zero=g.compare(g.math('ABSOLUTE',value),0.,'LESS_EQUAL')
            boundary=g.either(g.compare(g.math('ABSOLUTE',previous),0.,'GREATER_THAN'),
                              g.compare(g.math('ABSOLUTE',following),0.,'GREATER_THAN'))
            touch=g.store(mandatory,'st_bundle_gap_event',event_kind+1,'INT')
            events.append(_select(g,touch,g.all(zero,boundary),'Exact threshold touch or constant-threshold interval end'))
    if finite_terminal_contact:
        from . import bundle_event_nodes
        # Initially qualify local-difference discovery with finite contact and
        # narrow-infill caps. Existing overlap/chart families keep their rows.
        stable_events=bundle_event_nodes.evaluate(g,lookups,mandatory,lateral,minimum_band)
        stable_active=bundle_event_nodes.narrow_cap_active(g,cap_active,raw_boundaries,lateral)
        events=[g.switch(stable_active,_join(g,*events),stable_events,'GEOMETRY',
            'Local-difference events for finite narrow terminal caps')]
    critical_events=_join(g,*events)
    anchors=None
    if event_sampling:
        endpoints=_select(g,mandatory,g.either(g.compare(index,0,kind='INT'),
            g.compare(index,g.math('SUBTRACT',count,1.),kind='INT')),'Exact terminal anchors')
        anchor_parts=[endpoints,critical_events]
        if local_terminal_chart:
            anchor_parts.append(bundle_terminal_chart_nodes.anchor_rows(g,metric_parts[0],local_chart,
                identity_ends=identity_ends))
        anchors=_unique_metric_rows(g,_sorted(g,_join(g,*anchor_parts),
            g.named('st_bundle_metric','FLOAT'),'Ordered distinct Bundle topology anchors'))
    mandatory = _union_metric(g, [mandatory, *events])
    count = _size(g, mandatory)
    gap_field = query(g.named('st_bundle_metric', 'FLOAT'))[4]
    minimum_gap = g.stat(mandatory, gap_field)
    maximum_gap = g.stat(mandatory, gap_field, output='Max')
    has_caps = g.all(g.compare(minimum_gap, minimum_band, 'LESS_THAN'),
                     g.compare(maximum_gap, minimum_band, 'GREATER_THAN'))
    spans = g.node('GeometryNodeMeshLine', 'Densify only after all physical events are mandatory')
    g.set(g.math('SUBTRACT', count, 1.), spans.inputs['Count'])
    sa = g.sample(mandatory, g.named('st_bundle_metric', 'FLOAT'), index, 'FLOAT')
    sb = g.sample(mandatory, g.named('st_bundle_metric', 'FLOAT'), g.math('ADD', index, 1.), 'FLOAT')
    local_cell = target_cell
    if transition_cell_size is not None:
        ga, gb = query(sa)[4], query(sb)[4]
        threshold = g.math('MULTIPLY', 2., minimum_band)
        # The +/-2*minimum_band roots are mandatory, so midpoint classification
        # covers the whole open interval without refining its outside neighbor
        # merely because they share one threshold endpoint.
        midpoint_gap = g.math('MULTIPLY', .5, g.math('ADD', ga, gb))
        near_transition = g.all(has_caps, g.compare(g.math('ABSOLUTE', midpoint_gap), threshold, 'LESS_THAN'))
        local_cell = g.switch(near_transition, target_cell, g.math('MINIMUM', target_cell, transition_cell_size))
    subdivisions = g.math('MAXIMUM', 1., g.math('CEIL', g.math('DIVIDE',
                                  g.math('SUBTRACT', sb, sa), g.math('MAXIMUM', .01, local_cell))))
    spans_geo = g.store(spans.outputs['Mesh'], 'st_axis_sa', sa)
    spans_geo = g.store(spans_geo, 'st_axis_sb', sb)
    spans_geo = g.store(spans_geo, 'st_axis_subdivisions', subdivisions, 'INT')
    total = g.math('ADD', 1., g.stat(spans_geo, subdivisions, output='Sum'))
    budget = g.compare(total, MAX_OUTPUT_ROWS, 'LESS_EQUAL')
    duplicate = g.node('GeometryNodeDuplicateElements', 'Bounded uniform physical axial intervals')
    duplicate.domain = 'POINT'
    g.set(g.switch(budget, None, spans_geo, 'GEOMETRY'), duplicate.inputs['Geometry'])
    g.set(g.named('st_axis_subdivisions'), duplicate.inputs['Amount'])
    f = g.math('DIVIDE', duplicate.outputs['Duplicate Index'], g.named('st_axis_subdivisions'))
    metric = g.math('ADD', g.named('st_axis_sa', 'FLOAT'), g.math('MULTIPLY', f,
        g.math('SUBTRACT', g.named('st_axis_sb', 'FLOAT'), g.named('st_axis_sa', 'FLOAT'))))
    dense = g.store(duplicate.outputs['Geometry'], 'st_bundle_metric', metric)
    dense = g.store(dense, 'st_station_knot',
                    g.compare(duplicate.outputs['Duplicate Index'], 0, kind='INT'), 'BOOLEAN')
    endpoint = g.node('GeometryNodeMeshLine', 'Final physical Bundle station')
    endpoint.inputs['Count'].default_value = 1
    final = g.store(endpoint.outputs['Mesh'], 'st_bundle_metric', length)
    final = g.store(final, 'st_station_knot', True, 'BOOLEAN')
    table = _sorted(g, _join(g, dense, final), g.named('st_bundle_metric', 'FLOAT'), 'Final shared physical station rows')
    table = g.store(table, 'st_station_t', g.math('DIVIDE', g.named('st_bundle_metric', 'FLOAT'), g.math('MAXIMUM', length, 1e-8)))
    mixed_sampling=False
    if regular_sampling:
        from . import bundle_resample_nodes
        smooth=g.all(*(g.compare(g.sample(curves,g.named('st_sweep_interpolation','INT'),at,'INT','CURVE'),3,kind='INT')
                       for at in (owner,partner)))
        no_events=g.compare(_size(g,critical_events),0,kind='INT')
        active=g.all(smooth,no_events)
        # Certification must see every original boundary knot, including close
        # knots that the event-table union may spatially merge. Duplicates are
        # harmless to a maximum; missing breakpoints would invalidate the bound.
        regular,_count,certified,error=bundle_resample_nodes.construct(
            g,_join(g,*metric_parts),length,target_cell,query,active)
        if event_sampling:
            with_events=g.all(smooth,g.boolean('NOT',no_events))
            event_rows,_event_count,event_valid,event_error=bundle_resample_nodes.construct(
                g,_join(g,*metric_parts),length,target_cell,query,with_events,anchors=anchors,
                minimum_band=minimum_band,transition_cell=transition_cell_size,has_caps=has_caps)
            regular=g.switch(with_events,regular,event_rows,'GEOMETRY')
            certified=g.switch(with_events,certified,event_valid,'BOOLEAN')
            active=smooth
        if uniform_separated:
            # Exact controls remain mandatory. Smooth curves use coarse
            # intervals instead: nearly coincident control projections are
            # not hard corners, and all source knots still certify the error.
            # Local refinement avoids globally dense rows for one width taper.
            # Mixed contact events retain their existing construction unless
            # the explicit exact-member experiment below is enabled.
            exact=g.all(*(g.compare(g.sample(curves,g.named('st_sweep_interpolation','INT'),at,'INT','CURVE'),0,kind='INT')
                          for at in (owner,partner)))
            eligible=g.all(g.either(exact,smooth),no_events,g.compare(minimum_gap,minimum_band,'GREATER_EQUAL'),
                g.boolean('NOT',cap_active),g.either(smooth,g.boolean('NOT',terminal_alignment)))
            if uniform_mixed:
                from . import bundle_mixed_rows_nodes
                mixed_sampling=bundle_mixed_rows_nodes.eligibility(g,curves,owner,partner,
                    metric_parts,query,lateral,minimum_band,cap_active,terminal_alignment,
                    local_chart=local_chart if independent_terminal_charts else False,
                    physical_caps=independent_cap_active)
                eligible=g.either(eligible,mixed_sampling)
            # A smooth terminal chart changes lookup coordinates, not the
            # physical boundaries. Its derivative-break anchors are already
            # included below and every boundary knot still certifies the
            # output. Exact-mode chart control propagation remains separate.
            controls=_select(g,_join(g,*metric_parts),g.named('st_axis_control','BOOLEAN'),
                'Every original exact-member control retained as a physical anchor')
            controls=g.switch(smooth,controls,_smooth_macro_anchors(g,length,target_cell),'GEOMETRY',
                'Exact control anchors or coarse smooth refinement intervals')
            exact_anchors=_unique_metric_rows(g,_sorted(g,_join(g,anchors,controls),
                g.named('st_bundle_metric','FLOAT'),'Exact controls and terminal anchors for separated Bundle rows'))
            exact_rows,_exact_count,exact_valid,_exact_error=bundle_resample_nodes.construct(
                g,_join(g,*metric_parts),length,target_cell,query,eligible,anchors=exact_anchors,
                minimum_band=minimum_band,transition_cell=transition_cell_size,has_caps=has_caps)
            regular=g.switch(eligible,regular,exact_rows,'GEOMETRY')
            certified=g.switch(eligible,certified,exact_valid,'BOOLEAN')
            active=g.either(active,eligible)
        table=g.switch(active,table,regular,'GEOMETRY','Certified regular rows for smooth event-free Bundle spans')
        table=g.store(table,'st_bundle_regular_rows',active,'BOOLEAN')
        budget=g.switch(active,budget,certified,'BOOLEAN')
    valid = g.all(boundary_valid, mapping_valid, budget)
    code = g.switch(g.all(boundary_valid, budget), CERTIFICATE_CODE,
                    g.switch(mapping_valid, MAPPING_CODE, 0, 'INT'), 'INT')
    return {'table': table, 'ny': _size(g, table), 'valid': valid, 'code': code,
            'query': query, 'source_rank': source_rank, 'length': length, 'events': _join(g, *events),
            'boundary_valid': boundary_valid, 'mapping_valid': mapping_valid,
            'terminal_alignment': terminal_alignment,
            'local_terminal_chart': local_chart,
            'free_cap_body': cap_active, 'raw_boundaries': raw_boundaries,
            'cap_ends': cap_ends, 'independent_cap_active': independent_cap_active,
            'cap_depth': cap_depth,
            'source_table': source, 'source_count': nsource, 'axis': axis, 'origin': origin,
            'boundary_records': metric_parts,
            'mixed_sampling': mixed_sampling,
            'minimum_gap': minimum_gap, 'maximum_gap': maximum_gap}
